using IdleIntelligence.Core;using NUnit.Framework;
namespace IdleIntelligence.Tests {public sealed class ResetControlTests {
 [Test]public void DisablingOrPausingCancelsOnlyTheOriginalMatchingIntent(){var s=Game.New(1000000);s.Prestige.agent=true;s.Meta.axiomAuto=true;s.Prestige.resetIntent=true;s.Prestige.intentResearch=new[]{"dataGeneration"};ResetControls.TogglePrestige(s);Assert.That(s.Prestige.agent,Is.False);Assert.That(s.Prestige.resetIntent,Is.False);s.Prestige.resetIntent=true;s.Meta.intentAxiom=true;ResetControls.TogglePrestige(s);Assert.That(s.Prestige.resetIntent,Is.True,"Prestige toggle preserves an axiom intent");ResetControls.ToggleAxiom(s);Assert.That(s.Prestige.resetIntent,Is.False);s.Prestige.resetIntent=true;var paused=ResetControls.Pause(s);Assert.That(paused.Prestige.agent,Is.False);Assert.That(paused.Meta.axiomAuto,Is.False);Assert.That(paused.Prestige.resetIntent,Is.False);Assert.That(PrestigeAutomation.Agent(paused).Prestige.resets,Is.Zero);Assert.That(s.Prestige.resetIntent,Is.True,"Pure public action");}
}}
